def computed_example(number: int, results: dict[str, object]) -> str:
    if number == 1:
        row = results["floating_point"]
        return f"NumPy reports spacing {row['unit_roundoff_spacing']:.6g} at 1.0; the half-spacing increment evaluates to {row['lost_increment']:.6g} in the specified expression order."
    if number == 2:
        rows = results["ode_convergence"]
        return f"At rtol={rows[0]['rtol']:.0e}, endpoint error is {rows[0]['absolute_error']:.4g}; at rtol={rows[-1]['rtol']:.0e}, it is {rows[-1]['absolute_error']:.4g}. The analytic endpoint is {rows[0]['analytic']:.8f}."
    if number == 3:
        period = results["astronomical_parameters"]["earth_orbit_period_day"]
        model = results["jpl_earth_validation"]
        independent = results["jpl_earth_scipy_crosscheck"]
        return f"Using Astropy GM_sun, the circular 1-AU Kepler period is {period:.5f} d. After one day, REBOUND and independent SciPy two-body runs differ from the DE441 Earth-center vector by {model['position_residual_km']:.1f} km and {independent['position_residual_km']:.1f} km respectively; the residual is model/frame scope, not an accuracy claim."
    if number == 4:
        rows = results["rebound_nbody_conservation"]
        return f"Across 12 years, the three-body WHFast relative energy error falls from {rows[0]['relative_energy_error']:.3g} at dt={rows[0]['dt_day']:.3f} d to {rows[-1]['relative_energy_error']:.3g} at dt={rows[-1]['dt_day']:.3f} d; angular-momentum and scaled momentum errors are tabulated separately."
    if number == 5:
        sound_left = math.sqrt(1.4 * 1.0 / 1.0)
        sound_right = math.sqrt(1.4 * 0.1 / 0.125)
        return f"For the declared Sod states and gamma=1.4, initial sound speeds are {sound_left:.3f} and {sound_right:.3f} in the dimensionless model; both values are computed from sqrt(gamma*p/rho)."
    if number == 6:
        rows = results["hydro_resolution_study"]
        return f"The density L1 discrepancy against the 512-zone reference decreases from {rows[0]['density_l1_vs_512']:.5f} at {int(rows[0]['cells'])} cells to {rows[-1]['density_l1_vs_512']:.5f} at {int(rows[-1]['cells'])}; measured mass errors are listed independently."
    if number == 7:
        row = results["radiative_transfer"][2]
        return f"At tau={row['tau']}, the exact intensity is {row['intensity_exact']:.7f}; SciPy DOP853 differs by {row['absolute_solver_error']:.3g}."
    if number == 8:
        rows = results["radiative_transfer"]
        return f"For the first-order thin approximation, relative intensity error is {rows[0]['thin_approx_relative_error']:.3g} at tau={rows[0]['tau']:g} and {rows[-1]['thin_approx_relative_error']:.3g} at tau={rows[-1]['tau']:g}; the tolerance defines whether either is acceptable."
    if number == 9:
        row = results["monte_carlo_transmission"][-1]
        return f"For tau={row['optical_depth']:g}, analytic transmission is {row['analytic_transmission']:.6f}; the seeded N={int(row['trials'])} estimate is {row['estimate']:.6f} +/- {row['standard_error']:.6f} (one standard error)."
    if number == 10:
        rows = results["importance_sampling"]
        return f"At N={int(rows[0]['trials'])}, ordinary-sampling standard error is {rows[0]['standard_error']:.5g}; the likelihood-weighted proposal gives {rows[1]['standard_error']:.5g}. One run is evidence for this seed, not a universal variance guarantee."
    if number == 11:
        row = results["radial_velocity_fit"]
        return f"The seeded fit returns K={row['fit'][0]:.4f} m/s, phase={row['fit'][1]:.5f} rad, gamma={row['fit'][2]:.4f} m/s, residual RMS={row['residual_rms_m_s']:.4f} m/s, and chi-square={row['weighted_chi2']:.3f} for {row['degrees_of_freedom']} degrees of freedom."
    if number == 12:
        row = results["beta_posterior"]
        return f"For k=84 of n=100 with a Beta(1,1) prior, {row['draw_count']:,} seeded Beta(85,17) draws give median {row['median']:.4f} and central 68% interval [{row['lower_68']:.4f}, {row['upper_68']:.4f}]."
    if number == 13:
        versions = results["software_versions"]
        return "The executed environment reports " + ", ".join(f"{name} {version}" for name, version in versions.items()) + "; the same pins are recorded in requirements.txt."
    return f"The final validation dossier retains four distinct measures: three-body energy drift {results['rebound_nbody_conservation'][-1]['relative_energy_error']:.3g}, shock L1 error {results['hydro_resolution_study'][-1]['density_l1_vs_512']:.5f}, transmission standard error {results['monte_carlo_transmission'][-1]['standard_error']:.5f}, and fitted residual RMS {results['radial_velocity_fit']['residual_rms_m_s']:.4f} m/s."


def references_html() -> str:
    return "<ul>" + "".join(f"<li><a href='{url}'>{html.escape(title)}</a></li>" for title, url in REFERENCES) + "</ul>"


def build_lecture(number: int, item: dict[str, str], results: dict[str, object]) -> tuple[str, str]:
    title = item["title"]
    full_title = f"Lecture {number:02d}: {title}"
    figure_title, figure_svg, figure_caption = diagram(number, results)
    objectives = [item["question"], item["algorithm"].split(";")[0], item["limit"]]
    slides = [
        f"<section class='slide title'><p class='kicker'>ASTR 474 · Computational Astrophysics · Lecture {number:02d}</p><h1>{html.escape(full_title)}</h1><p>{html.escape(item['question'])}</p><p class='small'>14-week course · 3 credits · Week {number}</p></section>",
        f"<section class='slide'><p class='kicker'>Motivation</p><h2>{html.escape(item['question'])}</h2><p>{html.escape(item['concept'])}</p><p>Today’s result must be interpretable as a physical statement with declared data, algorithm, uncertainty, and a check that could fail.</p></section>",
        "<section class='slide'><p class='kicker'>Learning objectives</p><h2>After this lecture, you can</h2><ul>" + "".join(f"<li>{html.escape(text)}</li>" for text in objectives) + "</ul></section>",
        f"<section class='slide'><p class='kicker'>Physical and mathematical model</p><h2>State what is being evolved</h2><p>{html.escape(item['concept'])}</p><div class='equation'>\\[{item['equation']}\\]</div><p>Define the state, coordinates, units, initial/boundary conditions, and domain before interpreting solver output.</p></section>",
        f"<section class='slide'><p class='kicker'>Numerical method</p><h2>Algorithm choice is a modeling decision</h2><p>{html.escape(item['algorithm'])}</p><ol><li>Write the model and its assumptions.</li><li>Choose a solver and identify its stability, accuracy, and conservation properties.</li><li>Record configuration, tolerances or timestep, and output sampling.</li><li>Compare against an analytic limit, independent method, or controlled refinement.</li></ol></section>",
        f"<section class='slide'><p class='kicker'>Visual reasoning</p><h2>{html.escape(figure_title)}</h2><figure class='figure'>{figure_svg}<figcaption>{html.escape(figure_caption)}</figcaption></figure></section>",
        f"<section class='slide'><p class='kicker'>Computed example</p><h2>One result, with a check</h2><p>{html.escape(computed_example(number, results))}</p><p>Inputs and method are generated by <code>src/astr474_computations.py</code>; the machine-readable values are in <code>data/generated/computed_results.json</code>.</p><div class='callout'>{html.escape(item['limit'])}</div></section>",
        f"<section class='slide'><p class='kicker'>Verification</p><h2>What would falsify this result?</h2><ul><li>Repeat with a smaller timestep, tighter tolerance, or finer spatial grid.</li><li>Track conservation or residual structure in addition to visual agreement.</li><li>Check units, coordinate frame, boundary conditions, and invariants independently.</li><li>Change a random seed when the method is stochastic; report the resulting sampling uncertainty.</li></ul><p>Do not report a smoother curve as proof of convergence.</p></section>",
        f"<section class='slide'><p class='kicker'>Failure modes</p><h2>Numerical agreement has a domain</h2><p>{html.escape(item['limit'])}</p><p>Solver error, discretization error, stochastic error, parameter uncertainty, and model discrepancy are different quantities. Diagnose and report them separately.</p></section>",
        f"<section class='slide'><p class='kicker'>Active reasoning</p><h2>Make a prediction before rerunning</h2><p>{html.escape(item['question'])}</p><p>State a measurable outcome, a competing explanation, and the smallest computation that distinguishes them. Include an expected direction or scaling, then test it.</p></section>",
        f"<section class='slide'><p class='kicker'>Workflow</p><h2>From parameters to auditable output</h2><p>{html.escape(item['algorithm'])}</p><p>Record the exact command, package versions, data path, random seed if applicable, and output checksum. Keep raw inputs unchanged and generated files separate.</p></section>",
        f"<section class='slide'><p class='kicker'>Transfer</p><h2>Lab and problem-set connection</h2><p>{html.escape(item['bridge'])}</p><p>Submit plots with labeled axes/units, a concise uncertainty argument, and enough code or intermediate values for a peer to reproduce the claim.</p></section>",
        f"<section class='slide'><p class='kicker'>Synthesis</p><h2>Three durable checks</h2><ol><li>Does the implemented equation match the intended physical model?</li><li>Does the numerical result converge under a controlled method change?</li><li>Does the interpretation stay inside the validity and provenance limits?</li></ol><p>{html.escape(item['limit'])}</p></section>",
        f"<section class='slide'><p class='kicker'>Sources</p><h2>Technical references</h2>{references_html()}<p class='small'>Data and provenance details are recorded in <a href='../reference-log.md'>reference-log.md</a>. Last updated {__import__('datetime').date.today().isoformat()}.</p></section>",
    ]
    slide_doc = page(full_title, "<div class='deck'>" + "".join(slides) + "</div>")
    notes_sections = f"""
<section><h2>Problem and physical meaning</h2><p>{html.escape(item['concept'])}</p><p>{html.escape(item['question'])} Begin from the scientific observable or state variable, and name what is directly specified versus inferred. The model should be simple enough to validate, but not quietly presented as the entire astrophysical system.</p></section>
<section><h2>Model and derivation</h2><p>The governing expression for this lecture is:</p><div class='equation'>\\[{item['equation']}\\]</div><p>Define the symbols and the independent variable before numerical evaluation. Dimensional analysis checks that both sides have matching units; if the model is dimensionless, state the adopted scale factors and the transformation back to physical units.</p><p>{html.escape(item['concept'])}</p></section>
<section><h2>Numerical implementation</h2><p>{html.escape(item['algorithm'])}</p><p>Keep physical quantities and numerical arrays conceptually separate. Convert units at well-defined boundaries, preserve raw inputs, and record dtype, solver, tolerances/timestep, grid, and software versions. A numerical method is part of the model evidence, not an invisible implementation detail.</p></section>
<section><h2>Worked, programmatically computed example</h2><p>{html.escape(computed_example(number, results))}</p><p>These values are generated in <code>src/astr474_computations.py</code>, then shared with lecture/lab/assignment renderers. Re-run the generator after changing an input; do not hand-edit a displayed result without recomputing dependent artifacts.</p><p>At least one independent check is required: an analytic solution, a second numerical method, a conservation law, or a controlled convergence sequence. When these disagree, diagnose units, frame, discretization, source terms, and model scope before selecting a result.</p></section>
<section><h2>Error budget and limitations</h2><p>{html.escape(item['limit'])}</p><p>Classify each uncertainty before combining terms: local/global solver error, timestep or spatial discretization, Monte Carlo sampling, parameter uncertainty, measurement uncertainty, and model discrepancy are not interchangeable. Conservation can test internal consistency but does not prove the model is physically complete.</p></section>
<section><h2>Connection to evidence and research practice</h2><p>{html.escape(item['bridge'])}</p><p>For real parameters, the source record distinguishes the fetched product and epoch from derived values. For synthetic experiments, the initial conditions, generator, seed, and exact file are recorded. A simulation is not an observation, even when its parameters resemble a real object.</p></section>
<section><h2>Misconceptions to avoid</h2><ul><li>More displayed digits do not imply more physical accuracy.</li><li>A successful solver exit or smooth plot does not establish convergence.</li><li>Agreement between two solvers with the same wrong model is not independent physical validation.</li><li>A formal covariance or Monte Carlo interval is conditional on the adopted model and noise process.</li></ul></section>
<section><h2>Study and review questions</h2><ol><li>{html.escape(item['question'])}</li><li>Which numerical parameter would you vary first, what observable would you track, and how would you know the sequence reached an asymptotic regime?</li><li>Design one independent check and state what failure would change your scientific interpretation.</li></ol><p>Preparation for the next lecture: explain how this method's assumptions change when the problem becomes more coupled, stochastic, or data-driven.</p></section>
"""
    note_detail = NOTE_DETAILS[number - 1]
    detail_questions = "".join(f"<li>{html.escape(question)}</li>" for question in note_detail["questions"])
    detail_meetings = "".join(f"<li>{html.escape(meeting)}</li>" for meeting in note_detail["meetings"])
    notes_sections += f"""
<section><h2>Lecture-specific derivation and assumptions</h2><p>{html.escape(note_detail['derivation'])}</p></section>
<section><h2>Algorithm trace and computed-output interpretation</h2><p>{html.escape(note_detail['trace'])}</p><p><strong>Computed result:</strong> {html.escape(computed_example(number, results))}</p><p>{html.escape(note_detail['interpretation'])}</p></section>
<section><h2>Two-meeting teaching arc</h2><p>Each weekly module is taught in two 75-minute meetings. The sequence below includes a formative check in each meeting and is intended to use the lecture's worked computation, not merely present it.</p><ol>{detail_meetings}</ol></section>
<section><h2>Targeted study questions</h2><ol>{detail_questions}</ol></section>
"""
    note_title = full_title + " — Lecture Notes"
    note_doc = page(note_title, f"<header><div><p class='kicker'>ASTR 474 · Lecture {number:02d} · Study notes</p><h1>{html.escape(note_title)}</h1><p>{html.escape(item['question'])}</p></div></header><main>{notes_sections}<p class='small'>References and provenance: <a href='../reference-log.md'>course reference log</a>. Generated {__import__('datetime').date.today().isoformat()}.</p></main>")
    return slide_doc, note_doc


def build_lab(number: int, item: dict[str, object], results: dict[str, object]) -> str:
    worked = computed_example([2,3,4,6,8,10,14][number-1], results)
    procedure = "".join(f"<li>{html.escape(step)}</li>" for step in item["procedure"])
    return page(f"ASTR 474 Lab {number:02d}: {item['title']}", f"""
<header><div><p class='kicker'>ASTR 474 · Computational Lab {number:02d}</p><h1>Lab {number:02d}: {html.escape(item['title'])}</h1><p>{html.escape(item['focus'])}</p></div></header><main>
<section><h2>Purpose and learning objectives</h2><p>{html.escape(item['focus'])}. This investigation develops a numerical method and tests its output against a declared benchmark, invariant, uncertainty model, or independent implementation.</p><ul><li>Run a specified scientific workflow from the pinned environment.</li><li>Measure an explicit numerical or statistical diagnostic with units and provenance.</li><li>Separate numerical error from physical model discrepancy and interpret a limitation.</li></ul></section>
<section><h2>Preparation, setup, and inputs</h2><p><strong>Software:</strong> CPython 3.14.6; dependencies in <a href='../requirements.txt'>requirements.txt</a>. From repository root run <code>.venv/Scripts/python.exe materials/ASTR474/src/astr474_computations.py</code>. Then use the corresponding CSV/JSON under <code>materials/ASTR474/data/generated/</code>. Required data: {html.escape(item['dataset'])}.</p><p><strong>Apparatus:</strong> computer with local CPU, terminal, text editor, and browser; no telescope, GPU, network account, or paid service is required. Preserve the generated input files and record file hash/version.</p><p><strong>Model scope:</strong> {html.escape(item['synthetic'])}</p></section>
<section><h2>Procedure</h2><ol>{procedure}</ol></section>
<section><h2>Measurement record</h2><table><thead><tr><th>Quantity</th><th>Value or field</th><th>Unit/convention</th><th>Source/method</th></tr></thead><tbody>
<tr><td>Input configuration</td><td>Record solver, version, seed, timestep/grid/tolerance</td><td>As defined by the experiment</td><td>Command line and source file</td></tr>
<tr><td>Primary diagnostic</td><td>Record every resolution/sample/fit row, not just the preferred result</td><td>State units and normalization</td><td>Generated CSV/JSON</td></tr>
<tr><td>Independent reference</td><td>{html.escape(worked)}</td><td>As stated in the generated example</td><td>Analytic/JPL/invariant cross-check</td></tr>
<tr><td>Uncertainty/sensitivity</td><td>Repeat with changed resolution, seed, parameter, or method</td><td>Report interval or relative change</td><td>Student analysis</td></tr>
</tbody></table></section>
<section><h2>Analysis and uncertainty</h2><p>{html.escape(item['uncertainty'])}</p><p>Plot the diagnostic against the controlled parameter; label axes, units, normalization, and reference. Explain any non-monotonic point rather than smoothing or dropping it. If propagating independent errors, state why independence is plausible; preserve correlated/common-mode terms separately.</p></section>
<section><h2>Deliverables and assessment</h2><ol><li>Runnable source or notebook export with command, package versions, and all input/output paths.</li><li>One scientific figure plus a machine-readable table of measurements and convergence/sampling/residual diagnostics.</li><li>A 700-1000 word technical report describing model, method, validation, uncertainty categories, and one failed assumption.</li><li>A short claim-evidence table separating result, numerical check, and domain limitation.</li></ol><p>Rubric: 30% correct method and setup; 25% validation and numerical diagnostics; 20% uncertainty/provenance; 15% physical interpretation; 10% clarity and reproducibility. Revisions and resubmissions are encouraged under the syllabus mastery policy.</p></section>
<section><h2>Data and source provenance</h2><p>{html.escape(item['synthetic'])} Provenance levels, request records, and source verification limits are documented in <a href='../reference-log.md'>reference-log.md</a>; generated files and seeds are documented in <a href='../data/README.md'>data/README.md</a>.</p><p>References: {references_html()}</p></section>
</main>""")


