def pset_numeric(number: int, results: dict[str, object]) -> str:
    indices = [2,3,4,6,8,10,14]
    return computed_example(indices[number-1], results)


def solution_content(number: int, problem: int, results: dict[str, object]) -> str:
    if number == 1 and problem == 1:
        row = results["floating_point"]
        return (f"Binary64 spacing at 1 is {row['unit_roundoff_spacing']:.17g}. Half of this is exactly halfway between adjacent representable numbers; ties-to-even rounds `1 + spacing/2` back to 1, so subtracting 1 returns {row['lost_increment']:.1f}. Reordering to `(1-1)+spacing/2` returns {row['reordered_increment']:.17g}. This is a rounding/cancellation example, not evidence that arbitrary algebraic rearrangement improves a physical model. The dtype is float64; the installed NumPy version is {results['software_versions']['numpy']}. Check by printing `np.spacing(np.float64(1))` and evaluating both parenthesizations. An acceptable alternative is to show the binary significand/tie rule directly, provided the expression order and dtype are explicit.")
    if number == 1 and problem == 2:
        rows = results["ode_convergence"]
        slope = float(np.polyfit(np.log10([row["rtol"] for row in rows]),
                                 np.log10([row["absolute_error"] for row in rows]), 1)[0])
        table = "".join(f"<tr><td>{row['rtol']:.0e}</td><td>{row['final']:.12g}</td><td>{row['absolute_error']:.4g}</td><td>{int(row['steps'])}</td></tr>" for row in rows)
        return (f"Separation gives y(t)=exp(-t), hence y(1)=e^-1={rows[0]['analytic']:.12g}. The generated RK45 run gives the following values:<table><thead><tr><th>rtol</th><th>y(1)</th><th>absolute error</th><th>reported points</th></tr></thead><tbody>{table}</tbody></table>The log-log slope across these four samples is {slope:.3f}; interpret it as a compact trend summary, not a convergence order because adaptive step counts/tolerances and roundoff are not a uniform grid-refinement experiment. The tightest result should not be assumed best beyond the observed error trend. Validate by comparing the analytic endpoint, tightening tolerances, and repeating with another method. A fixed-step method with a derived global-error estimate is an acceptable independent alternative.")
    if number == 1 and problem == 3:
        return "Use (1) an analytic solution such as y'=-y, y(0)=1, compared at several final times to exp(-t), and (2) a scale/unit metamorphic test: rescale the independent variable by a known time factor and verify the transformed solution, while deliberately mixing incompatible Astropy units to confirm rejection. Record endpoint error, solver settings, and units. The analytic test checks order/sign and accumulated error; the dimensional test can expose a units/scale defect that a self-consistent but dimensionally wrong solver may pass. Also test a constant derivative y'=c against y=y0+ct. Accept either analytic test if its closed form and tolerance are stated."
    if number == 2 and problem == 1:
        period = results["astronomical_parameters"]["earth_orbit_period_day"]
        return (f"For a circular test-particle orbit, GM_sun/r^2=v^2/r and v=2*pi*r/P. Therefore P=2*pi*sqrt(r^3/GM_sun). With r=1 AU and Astropy's GM_sun converted to AU^3/day^2, P={period:.6f} days. Using G and M separately gives the same expression when units are consistent; retaining Earth mass changes the central parameter to G(M_sun+M_earth) and is a negligible but definable correction. The check is dimensional: r^3/GM has units of time squared. The value is a circular two-body period, not a claim that the observed tropical year is exactly this duration.")
    if number == 2 and problem == 2:
        rebound = results["jpl_earth_validation"]
        scipy_result = results["jpl_earth_scipy_crosscheck"]
        return (f"Initialize from the Jan 1 target-399 state and propagate to the Jan 2 TDB epoch in the recorded J2000 ecliptic, AU/AU-day convention. The REBOUND Sun-relative Newtonian result differs from the Jan 2 vector by {rebound['position_residual_km']:.3f} km; independent DOP853 differs by {scipy_result['position_residual_km']:.3f} km. Both compare simplified Sun-Earth integrations with a DE441 ephemeris state, so the residual includes omitted perturbations and frame/center differences; it is not a pure integration error. Refine the WHFast timestep and DOP853 tolerance, and transform both states into one frame before attributing the remaining residual. An acceptable alternative is to compare a transformed velocity state as well, provided the frame and epoch conversion is explicit. Source values are level-2, not live-verified this session.")
    if number == 2 and problem == 3:
        rows = results["rebound_timestep_convergence"]
        table = "".join(f"<tr><td>{int(row['steps_per_period'])}</td><td>{row['dt_day']:.6g}</td><td>{row['relative_energy_error']:.4g}</td><td>{row['endpoint_position_error_au']:.4g}</td></tr>" for row in rows)
        return (f"The generated circular-orbit sweep is:<table><thead><tr><th>steps/orbit</th><th>dt (day)</th><th>relative energy error</th><th>one-period endpoint error (AU)</th></tr></thead><tbody>{table}</tbody></table>Choose the coarsest step whose relevant endpoint/invariant errors meet a declared science tolerance; energy conservation alone does not bound phase/position error. The sequence should be checked for an asymptotic trend before extrapolating. A direct comparison with an analytic Kepler state is an acceptable independent test; state whether the target is phase accuracy, energy behavior, or both.")
    if number == 3 and problem == 1:
        rows = results["rebound_nbody_conservation"]
        energy_ratio = rows[0]["relative_energy_error"] / rows[-1]["relative_energy_error"]
        angular_same = rows[-1]["relative_angular_momentum_error"] < rows[0]["relative_angular_momentum_error"]
        table = "".join(f"<tr><td>{int(row['steps_per_earth_year'])}</td><td>{row['relative_energy_error']:.4g}</td><td>{row['relative_angular_momentum_error']:.4g}</td><td>{row['scaled_momentum_error']:.4g}</td></tr>" for row in rows)
        return (f"For the declared 12-year synthetic setup, the energy-error ratio (coarsest/fine) is {energy_ratio:.4g}. The complete table is:<table><thead><tr><th>steps/year</th><th>relative energy error</th><th>relative angular-momentum error</th><th>scaled momentum error</th></tr></thead><tbody>{table}</tbody></table>Angular momentum has the same overall decrease with refinement: {angular_same}. Compare all three diagnostics rather than infer one invariant from another. WHFast's fixed-step symplectic structure often yields bounded energy error; the observed finite sequence is not a proof of universal monotonic convergence. Independent verification may integrate the same initial conditions with IAS15 at tighter tolerances.")
    if number == 3 and problem == 2:
        return ("For each body i, differentiate the Newtonian potential to obtain a_i=G*sum_(j!=i) m_j (r_j-r_i)/|r_j-r_i|^3. A close-approach timescale can be estimated as t_enc~b/v_rel or, when gravity dominates, t_dyn~sqrt(b^3/[G(m_i+m_j)]). The timestep must be much shorter than the smallest relevant encounter/orbital timescale, then be tested by refinement; no universal fraction is guaranteed for chaotic trajectories. The supplied hierarchy's orbital periods alone do not resolve an arbitrarily close encounter. Either timescale estimate is acceptable if its regime and units are explained.")
    if number == 3 and problem == 3:
        return ("Use IAS15 for a close encounter whose short dynamical timescale violates the fixed-step WHFast hierarchy/resolution assumptions; a suitable hybrid method is also acceptable if its encounter switching conditions are justified. Before trusting the result: (1) halve/tighten the adaptive tolerance or maximum step and compare encounter time, minimum separation, and outgoing state; (2) compare total energy/angular momentum before and after with appropriate allowance for adaptive non-symplectic drift. Also check collision/softening policy and conservation of center-of-mass momentum. A visually smooth trajectory is insufficient; state a quantitative convergence threshold.")
    if number == 4 and problem == 1:
        return ("Integrate each conservation law over a fixed interval and apply the divergence theorem. The conservative system is partial_t rho + partial_x(rho*u)=0; partial_t(rho*u)+partial_x(rho*u^2+p)=0; partial_t E+partial_x[u(E+p)]=0, where E=p/(gamma-1)+rho*u^2/2 for an ideal gas. Thus U=(rho,rho*u,E) and F=(rho*u,rho*u^2+p,u(E+p)). In finite volume, the net change in a cell is the incoming interface flux minus outgoing flux. Gravity adds momentum/energy source terms; radiation, magnetic fields, and viscosity alter the model. An equivalent integral derivation is acceptable if all conserved variables and closure assumptions are identified.")
    if number == 4 and problem == 2:
        rows = results["hydro_resolution_study"]
        ratios = [rows[i]["density_l1_vs_512"] / rows[i+1]["density_l1_vs_512"] for i in range(len(rows)-1)]
        table = "".join(f"<tr><td>{int(row['cells'])}</td><td>{row['density_l1_vs_512']:.6g}</td><td>{'' if i == 0 else f'{ratios[i-1]:.3f}'}</td><td>{row['relative_mass_error']:.3g}</td></tr>" for i,row in enumerate(rows))
        return (f"The successive coarse-grid error ratios are {', '.join(f'{value:.3f}' for value in ratios)}. Results:<table><thead><tr><th>cells</th><th>L1 density difference vs 512</th><th>previous/current ratio</th><th>relative mass error</th></tr></thead><tbody>{table}</tbody></table>Ratios near 2 are consistent with first-order error reduction but do not establish asymptotic order because the reference is also a diffusive 512-cell run and the discontinuities may remain under-resolved. Mass conservation is a separate diagnostic. A stronger alternative compares to an exact Sod Riemann solution at matching cell averages and final time.")
    if number == 4 and problem == 3:
        return ("A release-quality audit should (a) assert rho>0 and p>0 after every update, (b) compare integrated mass change with boundary flux, (c) run a uniform-state/no-flow test to detect spurious evolution at boundaries, and (d) add at least two production features such as higher-order reconstruction with a limiter, multidimensional geometry, gravity/source-term coupling, robust boundary conditions, positivity-preserving flux treatment, and comparison to exact Riemann solutions. The present Rusanov code is first order, one-dimensional, and pedagogical. Accept other test cases when the failure they isolate is explained and measurable.")
    if number == 5 and problem == 1:
        row = next(row for row in results["radiative_transfer"] if row["tau"] == 1.0)
        return (f"Solve dI/dtau=S-I by multiplying by e^tau: d(Ie^tau)/d tau=S e^tau. Integrating from 0 to tau gives I(tau)=I0 e^-tau+S(1-e^-tau). For I0=0.2, S=0.7, tau=1, I_exact={row['intensity_exact']:.8f}; DOP853 gives {row['intensity_scipy']:.8f}, absolute solver difference {row['absolute_solver_error']:.3g}. This checks the numerical integration against the analytic solution, not the constant-source slab against an atmosphere. An integrating-factor derivation or direct substitution into the ODE is acceptable; include the boundary condition.")
    if number == 5 and problem == 2:
        rows = results["radiative_transfer"]
        low = next(row for row in rows if row["tau"] == 0.1)
        high = next(row for row in rows if row["tau"] == 5.0)
        threshold = results["thin_limit_1_percent_tau"]
        def error_row(row: dict[str, float]) -> str:
            absolute = abs(row["thin_approx"] - row["intensity_exact"])
            return f"tau={row['tau']:g}: exact={row['intensity_exact']:.8f}, thin={row['thin_approx']:.8f}, absolute error={absolute:.8f}, relative error={row['thin_approx_relative_error']:.4%}"
        return (f"Using I0=0.2 and S=0.7, {error_row(low)}; {error_row(high)}. The computed first crossing of 1% relative intensity error is tau={threshold:.6f}. Check the root by evaluating the error immediately below and above it. Because I_exact is the relative-error denominator, this threshold is specific to these boundary/source values. A Taylor-remainder bound is an acceptable cross-check, but the numerical criterion must still be evaluated on the stated observable.")
    if number == 5 and problem == 3:
        return ("In a non-LTE atmosphere the source function is not generally the Planck function B_nu(T); it depends on level populations and the radiation field. For isotropic coherent-scattering illustration, S_nu=(1-epsilon)J_nu+epsilon B_nu, where epsilon is the photon-destruction probability and J_nu is the angle-averaged intensity. Non-grey opacity makes optical depth frequency-dependent; anisotropic scattering, redistribution, geometry, and coupled statistical equilibrium require an angular/frequency closure and boundary conditions. A constant grey S cannot represent these feedbacks. Accept a different scattering source-function derivation if it identifies the coupling and the approximation being relaxed.")
    if number == 6 and problem == 1:
        rows = results["monte_carlo_transmission"]
        table = "".join(f"<tr><td>{int(row['trials'])}</td><td>{round(row['estimate']*row['trials'])}</td><td>{row['estimate']:.5f}</td><td>{row['standard_error']:.5f}</td><td>{row['absolute_error']:.5f}</td></tr>" for row in rows)
        exact = rows[0]["analytic_transmission"]
        return (f"The analytic transmission at tau=2 is exp(-2)={exact:.7f}. The nested seeded sample gives:<table><thead><tr><th>N</th><th>successes (reconstructed from p_hat*N)</th><th>p_hat</th><th>plug-in SE</th><th>|p_hat-p|</th></tr></thead><tbody>{table}</tbody></table>The nominal SE is sqrt(p_hat(1-p_hat)/N); an interval such as p_hat +/- 1 SE is a diagnostic, not a universal confidence statement, especially at small N. Prefix estimates are correlated. Repeat with independent seeds for empirical coverage. Exact binomial intervals are an acceptable alternative and are preferable near probability boundaries.")
    if number == 6 and problem == 2:
        rows = results["importance_sampling"]
        return (f"Let the target success probability be p=exp(-4)={rows[0]['analytic']:.8f} and proposal success probability q=0.2. The target/proposal likelihood ratio is p/q={rows[0]['analytic']/0.2:.8f} on success and (1-p)/(1-q) on failure; for the indicator f=1(success), the failure contribution is zero. Therefore E_q[1(success)*p/q]=q*p/q=p, proving unbiasedness. At N=10,000, ordinary sampling gives {rows[0]['estimate']:.8f} +/- {rows[0]['standard_error']:.8f}; weighted sampling gives {rows[1]['estimate']:.8f} +/- {rows[1]['standard_error']:.8f} (one estimated SE). The result is seed-specific; compare multiple independent runs or analytic estimator variance. A derivation using sums over the two outcomes is equivalent.")
    if number == 6 and problem == 3:
        fit = results["radial_velocity_fit"]
        amplitude, phase, offset = fit["fit"]
        errors = fit["fit_standard_errors"]
        return (f"For v(t)=gamma+K sin(2*pi*t/11.2+phi), the seeded weighted fit gives K={amplitude:.4f} m/s, phi={phase:.5f} rad, gamma={offset:.4f} m/s; local standard errors are {errors[0]:.4f} m/s, {errors[1]:.5f} rad, and {errors[2]:.4f} m/s under the source's Jacobian covariance with residual-scale estimate. Weighted chi-square={fit['weighted_chi2']:.3f} for {fit['degrees_of_freedom']} degrees of freedom; residual RMS={fit['residual_rms_m_s']:.4f} m/s. Inspect residuals versus time and phase: a coherent additional periodicity, long-term trend, or phase-dependent variance would invalidate the fixed-period one-sinusoid/noise model. Because the supplied sigma is known, covariance without reduced-chi-square rescaling is also acceptable if explicitly justified; a linear sin/cos fit is an independent parameterization.")
    if number == 7 and problem == 1:
        rows = results["hydro_resolution_study"]
        fit = results["radial_velocity_fit"]
        return (f"Example audit, using the synthetic shock tube: <table><thead><tr><th>Evidence channel</th><th>Result</th><th>Interpretation</th></tr></thead><tbody><tr><td>Discretization</td><td>L1 difference falls from {rows[0]['density_l1_vs_512']:.5f} at 32 zones to {rows[-1]['density_l1_vs_512']:.5f} at 256 zones</td><td>Resolution sensitivity relative to a non-exact 512-zone reference</td></tr><tr><td>Conservation</td><td>finest-grid relative mass error {rows[-1]['relative_mass_error']:.3g}</td><td>Internal update check, not physical-model validation</td></tr><tr><td>Sampling</td><td>Not applicable to deterministic shock solver</td><td>No random sampling in this experiment</td></tr><tr><td>Parameter/measurement</td><td>Initial state is dimensionless and instructor-defined</td><td>No measured-parameter interval is claimed</td></tr><tr><td>Model discrepancy</td><td>1-D ideal-gas Euler, first-order Rusanov</td><td>Omitted multi-D, radiation, magnetic, and gravity physics remain unquantified</td></tr></tbody></table>Alternative: audit the seeded radial-velocity result, retaining its {fit['residual_rms_m_s']:.3f} m/s residual RMS as a model/noise diagnostic and distinguishing fit covariance from model inadequacy. Mark each uncertainty category inapplicable only with a reason.")
    if number == 7 and problem == 2:
        versions = results["software_versions"]
        return (f"The current environment records NumPy {versions['numpy']}, SciPy {versions['scipy']}, Astropy {versions['astropy']}, and REBOUND {versions['rebound']} under CPython 3.14.6. From a clean venv, install `materials/ASTR474/requirements.txt`, run `python materials/ASTR474/src/generate_astr474_package.py --stage all`, then run `python materials/ASTR474/src/validate_astr474_package.py --verify-checksums`. The validator compares generated files with `data/generated/SHA256SUMS`; a changed file must fail until the build regenerates the manifest from declared sources. Version pins do not guarantee bitwise identity across operating systems, compiler/BLAS builds, CPUs, or future random-generator implementations. An acceptable checksum alternative is `Get-FileHash -Algorithm SHA256` if the same file list and comparison procedure are supplied.")
    if number == 7 and problem == 3:
        row = results["radiative_transfer"][1]
        threshold = results["thin_limit_1_percent_tau"]
        return (f"Sample bounded abstract: We tested a constant-source slab with I0=0.2 and S=0.7 using an analytic formal solution and an independent DOP853 integration. At tau=0.1 the exact intensity is {row['intensity_exact']:.6f}; the first-order thin-limit approximation remains within 1% relative intensity error only up to tau approximately {threshold:.4f} for these parameters. This is a synthetic numerical benchmark, not an observed atmosphere. The result is validated against the closed-form solution, while frequency dependence, scattering, and non-LTE source functions remain outside the model. A student's abstract may instead summarize another course result if it reports the actual check, provenance level, and limitations without stronger precision claims. Attach the input, code/environment record, checksum manifest, and a second-method or analytic cross-check.")
    raise ValueError(f"No solution written for Problem Set {number}, Problem {problem}")


def build_problem_set(number: int, results: dict[str, object]) -> tuple[str, str, str]:
    title = ["Numerical Foundations and ODE Accuracy", "Orbital Integration and Ephemeris Validation", "N-Body Conservation and Close Encounters", "Hydrodynamics and Resolution", "Radiative Transfer and Approximation Validity", "Monte Carlo and Parameter Inference", "Reproducible Research Audit"][number-1]
    unit = ["Lectures 01-02", "Lecture 03", "Lecture 04", "Lectures 05-06", "Lectures 07-08", "Lectures 09-12", "Lectures 13-14"][number-1]
    problems = "".join(f"<article class='panel'><h2>Problem {number}.{i}</h2><p>{html.escape(text)}</p><p><strong>Deliver:</strong> derivation or code, units/conventions, a reproducible result, uncertainty or validation evidence, and a short physical interpretation.</p></article>" for i,text in enumerate(PSET_PROMPTS[number-1],1))
    due_week = [2, 3, 4, 6, 8, 12, 14][number-1]
    student = page(f"ASTR 474 Problem Set {number:02d}: {title}", f"<header><div><p class='kicker'>ASTR 474 · {unit}</p><h1>Problem Set {number:02d}: {html.escape(title)}</h1><p>Due: end of Week {due_week}</p></div></header><main><section><h2>Objectives and instructions</h2><p>Practice computational reasoning, quantitative analysis, validation, and scientific communication for {html.escape(unit.lower())}.</p><ul><li>Use SI or explicitly stated astronomical units consistently; show conversions and significant figures.</li><li>Cite all data, software, and adapted code. Distinguish supplied measured data from synthetic records.</li><li>Include runnable code and record environment, command, and seed where used.</li><li>Collaboration on concepts is permitted; each submitted derivation, code, and interpretation must be the student's own and contributors must be named.</li></ul><p>Revisions and resubmissions are encouraged to improve mastery and grade under the course policy.</p></section>{problems}<section><h2>Reproducibility check</h2><p>Use this generated reference result as one consistency check, not as a substitute for showing reasoning: {html.escape(pset_numeric(number, results))}</p><p>No textbook exercise is adopted for this course; problems are original and cite the primary software/data sources in the reference log.</p></section><section><h2>Submission</h2><p>Submit a readable PDF report, source code, environment/version record, and any generated tables/figures. The assignment is complete only when another student can rerun the command and identify the inputs and validation test.</p></section></main>")
    solution_blocks = []
    for problem_number in range(1, len(PSET_PROMPTS[number-1]) + 1):
        content = solution_content(number, problem_number, results)
        if "<table>" in content:
            before, table_and_after = content.split("<table>", 1)
            table, after = table_and_after.split("</table>", 1)
            content = f"<p>{before}</p><table>{table}</table><p>{after}</p>"
        else:
            content = f"<p>{content}</p>"
        solution_blocks.append(f"<section><h2>Problem {number}.{problem_number}: worked solution</h2>{content}</section>")
    solutions = "".join(solution_blocks)
    key = page(f"ASTR 474 Problem Set {number:02d} Solutions", f"<header><div><p class='kicker'>Instructor solution key</p><h1>Problem Set {number:02d}: {html.escape(title)} — Solutions</h1><p>Separate from student-facing assignment</p></div></header><main>{solutions}<section><h2>Scoring guide</h2><p>Each problem is scored for model/setup (25%), correct computation or derivation (30%), validation and uncertainty (25%), and physical interpretation/communication (20%). Accept alternative correct methods when they meet the same evidence standard. See assessment instructions for error classification and resubmission guidance.</p></section></main>")
    assessment = f"""# Problem Set {number:02d} Assessment Instructions

## Artifacts

Inspect the student's report/source, Problem Set {number:02d}, this solution key, course syllabus, and the referenced data/provenance records.

## Standards

- Independently recompute at least one numerical result using the stated inputs and units.
- Distinguish conceptual/model errors, arithmetic slips, unit/frame errors, code defects, statistical uncertainty, and communication gaps.
- Check that convergence, residual, conservation, or random-seed claims are supported by actual outputs, not prose alone.
- Verify citations and that synthetic data are not described as observed measurements.
- Reward a correct alternative method if its assumptions and validation are explicit; do not award full credit for unexplained output.

## Rubric and feedback

Use the per-problem model/computation/validation/interpretation weights in the solution key. Give actionable feedback that identifies the claim, evidence, and next test needed. Revisions and resubmissions are encouraged for improved mastery and grade; preserve the course's high standards and do not silently repair code before recording its behavior.
"""
    return student, key, assessment


def build_all() -> None:
    results = compute_results()
    for number, item in enumerate(LECTURES, 1):
        slides, notes = build_lecture(number, item, results)
        (ROOT / "lectures" / f"lecture-{number:02d}-slides.html").write_text(slides, encoding="utf-8")
        (ROOT / "lectures" / f"lecture-{number:02d}-notes.html").write_text(notes, encoding="utf-8")
    for number, item in enumerate(LABS, 1):
        (ROOT / "labs" / f"lab-{number:02d}.html").write_text(build_lab(number, item, results), encoding="utf-8")
    for number in range(1, 8):
        student, solution, assessment = build_problem_set(number, results)
        base = ROOT / "problem-sets"
        (base / f"problem-set-{number:02d}.html").write_text(student, encoding="utf-8")
        (base / f"problem-set-{number:02d}-solutions.html").write_text(solution, encoding="utf-8")
        (base / f"problem-set-{number:02d}-assessment.md").write_text(assessment, encoding="utf-8")
    (ROOT / "README.md").write_text("""# ASTR 474: Computational Astrophysics

Three-credit Year 4 elective. Catalog description and prerequisites are listed in `syllabus.html`.

This package contains 14 lecture/notes pairs, 7 computational labs, 7 problem sets, instructor solutions, and assessment instructions. All displayed computed values are generated by `src/astr474_computations.py`; visual and instructional pages are regenerated with `src/build_astr474_materials.py`. See `reference-log.md` for source status and per-record provenance.

Release status is recorded in `course-manifest.json` and `review-report.md`. Review release does not constitute approval for instructional use; local policies and human spot-checks remain necessary.
""", encoding="utf-8")
    print(f"Built {len(LECTURES)} lecture pairs, {len(LABS)} labs, and 7 problem-set bundles from shared computed results.")


if __name__ == "__main__":
    build_all()